import java.io.*;
import java.util.*;

public class Main {

    private static final String _A = "a";
    private static final String _B = "b";
    private static final String _C = "c";

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int n = fs.nextInt();
        int k = fs.nextInt();
        String s = fs.next();
        String t = fs.next();
        long result = find_best_score_can_make(s, t, k);
        System.out.println(result);
    }

    private static long find_best_score_can_make(String s, String t, int moves_n) {
        if (t.length() != 2) throw new AssertionError();
        if (t.charAt(0) == t.charAt(1)) {
            char t_char = t.charAt(0);
            int t_char_count = 0;
            for (int i = 0; i < s.length(); i++) {
                if (s.charAt(i) == t_char) t_char_count++;
            }
            t_char_count += moves_n;
            if (t_char_count > s.length()) t_char_count = s.length();
            return (long) t_char_count * (t_char_count - 1) / 2;
        }

        char t0 = t.charAt(0);
        char t1 = t.charAt(1);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch == t0) sb.append(_A);
            else if (ch == t1) sb.append(_B);
            else sb.append(_C);
        }
        s = sb.toString();

        Indices abc = _compute_abc_indices(s);

        long best_score = Long.MIN_VALUE;

        int max_c_start = Math.min(abc.c_indices.size(), moves_n);
        for (int c_start = 0; c_start <= max_c_start; c_start++) {
            int c_start_moves_spent = c_start;
            int moves_spent = c_start_moves_spent;
            int moves_remain = moves_n - moves_spent;
            if (moves_remain < 0) throw new AssertionError();

            int max_b_start = Math.min(abc.b_indices.size(), moves_remain);
            for (int b_start = 0; b_start <= max_b_start; b_start++) {
                int b_start_moves_spent = b_start;
                moves_spent = c_start_moves_spent + b_start_moves_spent;
                moves_remain = moves_n - moves_spent;
                if (moves_remain < 0) throw new AssertionError();

                char[] new_s = s.toCharArray();
                for (int i_i_c = 0; i_i_c < c_start; i_i_c++) {
                    int i_c = abc.c_indices.get(i_i_c);
                    new_s[i_c] = _A.charAt(0);
                }
                for (int i_i_b = 0; i_i_b < b_start; i_i_b++) {
                    int i_b = abc.b_indices.get(i_i_b);
                    new_s[i_b] = _A.charAt(0);
                }

                long curr_best_score = _find_best_score_can_make_with_fixed_starts(new_s, moves_remain);
                if (curr_best_score > best_score) best_score = curr_best_score;
            }
        }

        return best_score;
    }

    private static class Indices {
        List<Integer> a_indices;
        List<Integer> b_indices;
        List<Integer> c_indices;

        Indices(List<Integer> a, List<Integer> b, List<Integer> c) {
            this.a_indices = a;
            this.b_indices = b;
            this.c_indices = c;
        }
    }

    private static Indices _compute_abc_indices(String s) {
        List<Integer> a_indices = new ArrayList<>();
        List<Integer> b_indices = new ArrayList<>();
        List<Integer> c_indices = new ArrayList<>();
        for (int i = 0; i < s.length(); i++) {
            char char_ = s.charAt(i);
            if (char_ == _A.charAt(0)) {
                a_indices.add(i);
            } else if (char_ == _B.charAt(0)) {
                b_indices.add(i);
            } else {
                if (char_ != _C.charAt(0)) throw new AssertionError();
                c_indices.add(i);
            }
        }
        return new Indices(a_indices, b_indices, c_indices);
    }

    private static long _find_best_score_can_make_with_fixed_starts(char[] s, int moves_n) {
        long best_score = Long.MIN_VALUE;

        String sStr = new String(s);
        Indices abc = _compute_abc_indices(sStr);

        List<Integer> a_indices = abc.a_indices;
        List<Integer> b_indices = abc.b_indices;
        List<Integer> c_indices = abc.c_indices;

        int a_n = a_indices.size();
        int c_n = c_indices.size();

        int max_a_stop = a_indices.size();
        int max_c_stop = c_indices.size();

        class CStopHelper {
            int get_c_stop_by_moves_remain(int moves_remain) {
                int min_c_stop = max_c_stop - moves_remain;
                if (min_c_stop < 0) min_c_stop = 0;
                int c_stop = min_c_stop;
                return c_stop;
            }
        }

        CStopHelper helper = new CStopHelper();

        int first_c_stop = helper.get_c_stop_by_moves_remain(moves_n);
        char[] new_s = _get_curr_s(s, a_indices, max_a_stop, c_indices, first_c_stop);
        long curr_score = _get_curr_score_slow_way(new_s);

        if (curr_score > best_score) best_score = curr_score;

        long[] old_a_before = _compute_a_before(new String(new_s));
        String replaced = new String(new_s).replace(_C, _B);
        long[] old_b_after_if_all_c_are_b = _compute_b_after(replaced);

        int curr_b_to_c_before_a = 0;
        int curr_a_to_b_after_c = 0;

        Integer prev_c_stop = null;
        int c_stop = first_c_stop;
        int c_stop_moves_spent = max_c_stop - c_stop;

        int min_a_stop = max_a_stop - moves_n;
        min_a_stop = Math.max(min_a_stop, 0);
        for (int a_stop = max_a_stop - 1; a_stop >= min_a_stop; a_stop--) {
            int a_stop_moves_spent = max_a_stop - a_stop;
            int moves_spent = a_stop_moves_spent;
            int moves_remain = moves_n - moves_spent;
            if (moves_remain < 0) throw new AssertionError();

            if (a_stop_moves_spent <= 0) throw new AssertionError();

            int curr_a_index = a_indices.get(a_stop);
            int curr_b_to_c = c_stop;
            if (curr_b_to_c_before_a < curr_b_to_c
                    && c_indices.get(curr_b_to_c_before_a) < curr_a_index) {
                while (curr_b_to_c_before_a < curr_b_to_c
                        && c_indices.get(curr_b_to_c_before_a) < curr_a_index) {
                    curr_b_to_c_before_a++;
                }
            } else if (curr_b_to_c_before_a > 0
                    && c_indices.get(curr_b_to_c_before_a - 1) > curr_a_index) {
                while (curr_b_to_c_before_a > 0
                        && c_indices.get(curr_b_to_c_before_a - 1) > curr_a_index) {
                    curr_b_to_c_before_a--;
                }
            }

            int prev_a_stop_moves_spent = a_stop_moves_spent - 1;
            int curr_b_to_c_after_a = curr_b_to_c - curr_b_to_c_before_a;
            int new_b_after = prev_a_stop_moves_spent - curr_b_to_c_after_a;
            long b_after = old_b_after_if_all_c_are_b[curr_a_index] + new_b_after;
            curr_score -= b_after;
            curr_score += old_a_before[curr_a_index];

            prev_c_stop = c_stop;
            c_stop = helper.get_c_stop_by_moves_remain(moves_remain);
            c_stop_moves_spent = max_c_stop - c_stop;

            int diff = c_stop - prev_c_stop;
            if (diff != 0 && diff != 1) throw new AssertionError();
            if (diff == 1) {
                int prev_c_index = c_indices.get(prev_c_stop);
                int curr_a_to_b = a_n - a_stop;
                if (curr_a_to_b_after_c < curr_a_to_b
                        && a_indices.get(a_n - (curr_a_to_b_after_c + 1)) > prev_c_index) {
                    while (curr_a_to_b_after_c < curr_a_to_b
                            && a_indices.get(a_n - (curr_a_to_b_after_c + 1)) > prev_c_index) {
                        curr_a_to_b_after_c++;
                    }
                } else if (curr_a_to_b_after_c > 0
                        && a_indices.get(a_n - curr_a_to_b_after_c) < prev_c_index) {
                    while (curr_a_to_b_after_c > 0
                            && a_indices.get(a_n - curr_a_to_b_after_c) < prev_c_index) {
                        curr_a_to_b_after_c--;
                    }
                }

                int a_to_b_before = curr_a_to_b - curr_a_to_b_after_c;
                long curr_a_before = old_a_before[prev_c_index] - a_to_b_before;
                curr_score -= curr_a_before;
            }

            if (curr_score > best_score) best_score = curr_score;
        }

        return best_score;
    }

    private static char[] _get_curr_s(char[] s, List<Integer> a_indices, int a_stop,
                                      List<Integer> c_indices, int c_stop) {
        char[] res = Arrays.copyOf(s, s.length);
        for (int i_i_a = 0; i_i_a < a_stop; i_i_a++) {
            int i_a = a_indices.get(i_i_a);
            res[i_a] = _A.charAt(0);
        }
        for (int i_i_a = a_stop; i_i_a < a_indices.size(); i_i_a++) {
            int i_a = a_indices.get(i_i_a);
            res[i_a] = _B.charAt(0);
        }
        for (int i_i_c = 0; i_i_c < c_stop; i_i_c++) {
            int i_c = c_indices.get(i_i_c);
            res[i_c] = _C.charAt(0);
        }
        for (int i_i_c = c_stop; i_i_c < c_indices.size(); i_i_c++) {
            int i_c = c_indices.get(i_i_c);
            res[i_c] = _B.charAt(0);
        }
        return res;
    }

    private static long _get_curr_score_slow_way(char[] s) {
        long curr_score = 0;
        long a_accumulated = 0;
        for (char ch : s) {
            if (ch == _A.charAt(0)) {
                a_accumulated += 1;
            } else if (ch == _B.charAt(0)) {
                curr_score += a_accumulated;
            }
        }
        return curr_score;
    }

    private static long[] _compute_a_before(String s) {
        int n = s.length();
        long[] acc = new long[n];
        long sum = 0;
        for (int i = 0; i < n; i++) {
            sum += (s.charAt(i) == _A.charAt(0)) ? 1 : 0;
            acc[i] = sum;
        }
        long[] result = new long[n];
        result[0] = 0;
        for (int i = 1; i < n; i++) {
            result[i] = acc[i - 1];
        }
        return result;
    }

    private static long[] _compute_b_after(String s) {
        int n = s.length();
        long[] acc = new long[n];
        long sum = 0;
        for (int i = n - 1; i >= 0; i--) {
            sum += (s.charAt(i) == _B.charAt(0)) ? 1 : 0;
            acc[i] = sum;
        }
        long[] result = new long[n];
        for (int i = 0; i < n - 1; i++) {
            result[i] = acc[i + 1];
        }
        result[n - 1] = 0;
        return result;
    }

    private static class FastScanner {
        private final BufferedReader br;
        private StringTokenizer st;

        FastScanner(InputStream is) {
            br = new BufferedReader(new InputStreamReader(is));
        }

        String next() throws IOException {
            while (st == null || !st.hasMoreTokens()) {
                String line = br.readLine();
                if (line == null) return null;
                st = new StringTokenizer(line);
            }
            return st.nextToken();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    private static final String _A = "a";
    private static final String _B = "b";
    private static final String _C = "c";

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] nk = br.readLine().split(" ");
        int n = Integer.parseInt(nk[0]);
        int k = Integer.parseInt(nk[1]);
        String s = br.readLine();
        String t = br.readLine();
        long result = find_best_score_can_make(s, t, k);
        System.out.println(result);
    }

    private static long find_best_score_can_make(String s, String t, int moves_n) {
        if (t.length() != 2) throw new AssertionError();
        if (t.charAt(0) == t.charAt(1)) {
            char t_char = t.charAt(0);
            int t_char_count = 0;
            for (int i = 0; i < s.length(); i++) {
                if (s.charAt(i) == t_char) t_char_count++;
            }
            t_char_count += moves_n;
            if (t_char_count > s.length()) {
                t_char_count = s.length();
            }
            return (long) t_char_count * (t_char_count - 1) / 2;
        }

        char[] sc = s.toCharArray();
        char t0 = t.charAt(0);
        char t1 = t.charAt(1);
        for (int i = 0; i < sc.length; i++) {
            char ch = sc[i];
            if (ch == t0) sc[i] = _A.charAt(0);
            else if (ch == t1) sc[i] = _B.charAt(0);
            else sc[i] = _C.charAt(0);
        }
        s = new String(sc);

        int[][] abc = _compute_abc_indices(s);
        int[] a_indices = abc[0];
        int[] b_indices = abc[1];
        int[] c_indices = abc[2];

        long best_score = Long.MIN_VALUE;

        int max_c_start = Math.min(c_indices.length, moves_n);
        for (int c_start = 0; c_start <= max_c_start; c_start++) {
            int c_start_moves_spent = c_start;
            int moves_spent = c_start_moves_spent;
            int moves_remain = moves_n - moves_spent;
            if (moves_remain < 0) throw new AssertionError();

            int max_b_start = Math.min(b_indices.length, moves_remain);
            for (int b_start = 0; b_start <= max_b_start; b_start++) {
                int b_start_moves_spent = b_start;
                moves_spent = c_start_moves_spent + b_start_moves_spent;
                moves_remain = moves_n - moves_spent;
                if (moves_remain < 0) throw new AssertionError();

                char[] new_s = s.toCharArray();
                for (int i_i_c = 0; i_i_c < c_start; i_i_c++) {
                    int i_c = c_indices[i_i_c];
                    new_s[i_c] = _A.charAt(0);
                }
                for (int i_i_b = 0; i_i_b < b_start; i_i_b++) {
                    int i_b = b_indices[i_i_b];
                    new_s[i_b] = _A.charAt(0);
                }

                long curr_best_score = _find_best_score_can_make_with_fixed_starts(new_s, moves_remain);
                best_score = Math.max(best_score, curr_best_score);
            }
        }

        return best_score;
    }

    private static int[][] _compute_abc_indices(String s) {
        List<Integer> a_list = new ArrayList<>();
        List<Integer> b_list = new ArrayList<>();
        List<Integer> c_list = new ArrayList<>();
        for (int i = 0; i < s.length(); i++) {
            char char_ = s.charAt(i);
            if (char_ == _A.charAt(0)) {
                a_list.add(i);
            } else if (char_ == _B.charAt(0)) {
                b_list.add(i);
            } else {
                if (char_ != _C.charAt(0)) throw new AssertionError();
                c_list.add(i);
            }
        }
        int[] a_indices = a_list.stream().mapToInt(Integer::intValue).toArray();
        int[] b_indices = b_list.stream().mapToInt(Integer::intValue).toArray();
        int[] c_indices = c_list.stream().mapToInt(Integer::intValue).toArray();
        return new int[][]{a_indices, b_indices, c_indices};
    }

    private static long _find_best_score_can_make_with_fixed_starts(char[] s, int moves_n) {
        long best_score = Long.MIN_VALUE;

        String sStr = new String(s);
        int[][] abc = _compute_abc_indices(sStr);
        int[] a_indices = abc[0];
        int[] b_indices = abc[1];
        int[] c_indices = abc[2];

        int a_n = a_indices.length;
        int c_n = c_indices.length;

        int max_a_stop = a_indices.length;
        int max_c_stop = c_indices.length;

        java.util.function.IntUnaryOperator get_c_stop_by_moves_remain = moves_remain -> {
            int min_c_stop = max_c_stop - moves_remain;
            if (min_c_stop < 0) {
                min_c_stop = 0;
            }
            int c_stop = min_c_stop;
            return c_stop;
        };

        int first_c_stop = get_c_stop_by_moves_remain.applyAsInt(moves_n);
        char[] new_s = _get_curr_s(s, a_indices, max_a_stop, c_indices, first_c_stop);
        long curr_score = _get_curr_score_slow_way(new_s);

        best_score = Math.max(best_score, curr_score);

        long[] old_a_before = _compute_a_before(new_s);
        String replaced = new String(new_s).replace(_C, _B);
        long[] old_b_after_if_all_c_are_b = _compute_b_after(replaced.toCharArray());

        int curr_b_to_c_before_a = 0;
        int curr_a_to_b_after_c = 0;

        Integer prev_c_stop = null;
        int c_stop = first_c_stop;
        int c_stop_moves_spent = max_c_stop - c_stop;

        int min_a_stop = max_a_stop - moves_n;
        min_a_stop = Math.max(min_a_stop, 0);
        for (int a_stop = max_a_stop - 1; a_stop >= min_a_stop; a_stop--) {
            int a_stop_moves_spent = max_a_stop - a_stop;
            int moves_spent = a_stop_moves_spent;
            int moves_remain = moves_n - moves_spent;
            if (moves_remain < 0) throw new AssertionError();

            if (a_stop_moves_spent <= 0) throw new AssertionError();

            int curr_a_index = a_indices[a_stop];
            int curr_b_to_c = c_stop;
            if (curr_b_to_c_before_a < curr_b_to_c
                    && c_indices[curr_b_to_c_before_a] < curr_a_index) {
                while (curr_b_to_c_before_a < curr_b_to_c
                        && c_indices[curr_b_to_c_before_a] < curr_a_index) {
                    curr_b_to_c_before_a += 1;
                }
            } else if (curr_b_to_c_before_a > 0
                    && c_indices[curr_b_to_c_before_a - 1] > curr_a_index) {
                while (curr_b_to_c_before_a > 0
                        && c_indices[curr_b_to_c_before_a - 1] > curr_a_index) {
                    curr_b_to_c_before_a -= 1;
                }
            }

            int prev_a_stop_moves_spent = a_stop_moves_spent - 1;
            int curr_b_to_c_after_a = curr_b_to_c - curr_b_to_c_before_a;
            int new_b_after = prev_a_stop_moves_spent - curr_b_to_c_after_a;
            long b_after = old_b_after_if_all_c_are_b[curr_a_index] + new_b_after;
            curr_score -= b_after;
            curr_score += old_a_before[curr_a_index];

            prev_c_stop = c_stop;
            c_stop = get_c_stop_by_moves_remain.applyAsInt(moves_remain);
            c_stop_moves_spent = max_c_stop - c_stop;

            int diff = c_stop - prev_c_stop;
            if (diff != 0 && diff != 1) throw new AssertionError();
            if (diff == 1) {
                int prev_c_index = c_indices[prev_c_stop];
                int curr_a_to_b = a_n - a_stop;
                if (curr_a_to_b_after_c < curr_a_to_b
                        && a_indices[a_n - (curr_a_to_b_after_c + 1)] > prev_c_index) {
                    while (curr_a_to_b_after_c < curr_a_to_b
                            && a_indices[a_n - (curr_a_to_b_after_c + 1)] > prev_c_index) {
                        curr_a_to_b_after_c += 1;
                    }
                } else if (curr_a_to_b_after_c > 0
                        && a_indices[a_n - curr_a_to_b_after_c] < prev_c_index) {
                    while (curr_a_to_b_after_c > 0
                            && a_indices[a_n - curr_a_to_b_after_c] < prev_c_index) {
                        curr_a_to_b_after_c -= 1;
                    }
                }

                int a_to_b_before = curr_a_to_b - curr_a_to_b_after_c;
                long curr_a_before = old_a_before[prev_c_index] - a_to_b_before;
                curr_score -= curr_a_before;
            }

            best_score = Math.max(best_score, curr_score);
        }

        return best_score;
    }

    private static char[] _get_curr_s(char[] s, int[] a_indices, int a_stop, int[] c_indices, int c_stop) {
        char[] res = Arrays.copyOf(s, s.length);
        for (int i_i_a = 0; i_i_a < a_stop; i_i_a++) {
            int i_a = a_indices[i_i_a];
            res[i_a] = _A.charAt(0);
        }
        for (int i_i_a = a_stop; i_i_a < a_indices.length; i_i_a++) {
            int i_a = a_indices[i_i_a];
            res[i_a] = _B.charAt(0);
        }
        for (int i_i_c = 0; i_i_c < c_stop; i_i_c++) {
            int i_c = c_indices[i_i_c];
            res[i_c] = _C.charAt(0);
        }
        for (int i_i_c = c_stop; i_i_c < c_indices.length; i_i_c++) {
            int i_c = c_indices[i_i_c];
            res[i_c] = _B.charAt(0);
        }
        return res;
    }

    private static long _get_curr_score_slow_way(char[] s) {
        long curr_score = 0;
        long a_accumulated = 0;
        for (char ch : s) {
            if (ch == _A.charAt(0)) {
                a_accumulated += 1;
            } else if (ch == _B.charAt(0)) {
                curr_score += a_accumulated;
            }
        }
        return curr_score;
    }

    private static long[] _compute_a_before(char[] s) {
        int n = s.length;
        long[] acc = new long[n];
        long sum = 0;
        for (int i = 0; i < n; i++) {
            sum += (s[i] == _A.charAt(0)) ? 1 : 0;
            acc[i] = sum;
        }
        long[] result = new long[n + 1];
        result[0] = 0;
        System.arraycopy(acc, 0, result, 1, n - 1);
        return result;
    }

    private static long[] _compute_b_after(char[] s) {
        int n = s.length;
        long[] acc = new long[n];
        long sum = 0;
        for (int i = n - 1; i >= 0; i--) {
            sum += (s[i] == _B.charAt(0)) ? 1 : 0;
            acc[i] = sum;
        }
        long[] result = new long[n];
        System.arraycopy(acc, 1, result, 0, n - 1);
        result[n - 1] = 0;
