        for (int i = 0; i < s.length(); i++) {
            char char_ = s.charAt(i);
            if (char_ == _A.charAt(0)) {
                a_indices.add(i);
            } else if (char_ == _B.charAt(0)) {
                b_indices.add(i);
            } else {
                if (char_ != _C.charAt(0)) throw new AssertionError();
                c_indices.add(i);
            }
        }
        return new ABCIndices(a_indices, b_indices, c_indices);
