            }
            t_char_count += moves_n;
            if (t_char_count > s.length()) t_char_count = s.length();
            return (long) t_char_count * (t_char_count - 1) / 2;
        }

        char[] sc = s.toCharArray();
        char t0 = t.charAt(0);
        char t1 = t.charAt(1);
        for (int i = 0; i < sc.length; i++) {
            char ch = sc[i];
            if (ch == t0) sc[i] = 'a';
            else if (ch == t1) sc[i] = 'b';
            else sc[i] = 'c';
        }
        s = new String(sc);

        ABCIndices indices = _compute_abc_indices(s);
        int[] a_indices = indices.a_indices;
        int[] b_indices = indices.b_indices;
        int[] c_indices = indices.c_indices;

        long best_score = Long.MIN_VALUE;

        int max_c_start = Math.min(c_indices.length, moves_n);
        for (int c_start = 0; c_start <= max_c_start; c_start++) {
            int c_start_moves_spent = c_start;
            int moves_spent = c_start_moves_spent;
            int moves_remain = moves_n - moves_spent;
            if (moves_remain < 0) throw new AssertionError();

            int max_b_start = Math.min(b_indices.length, moves_remain);
            for (int b_start = 0; b_start <= max_b_start; b_start++) {
                int b_start_moves_spent = b_start;
                moves_spent = c_start_moves_spent + b_start_moves_spent;
                moves_remain = moves_n - moves_spent;
                if (moves_remain < 0) throw new AssertionError();

                char[] new_s = s.toCharArray();
                for (int i_i_c = 0; i_i_c < c_start; i_i_c++) {
                    int i_c = c_indices[i_i_c];
