                a_accumulated += 1;
            } else if (ch == 'b') {
                curr_score += a_accumulated;
            }
        }
        return curr_score;
    }

    private static long[] _compute_a_before(String s) {
        int n = s.length();
        long[] result = new long[n + 1];
        long acc = 0;
        for (int i = 0; i < n; i++) {
            if (s.charAt(i) == 'a') acc += 1;
            result[i + 1] = acc;
        }
        long[] shifted = new long[n];
        System.arraycopy(result, 0, shifted, 0, n);
        return shifted;
    }

    private static long[] _compute_b_after(String s) {
        int n = s.length();
        long[] rev = new long[n + 1];
        long acc = 0;
        for (int i = n - 1; i >= 0; i--) {
            if (s.charAt(i) == 'b') acc += 1;
            rev[n - i] = acc;
        }
        long[] tmp = new long[n + 1];
        for (int i = 0; i <= n; i++) {
            tmp[i] = rev[n - i];
        }
        long[] result = new long[n];
        System.arraycopy(tmp, 1, result, 0, n);
        long[] shifted = new long[n];
        System.arraycopy(result, 0, shifted, 0, n - 1);
        shifted[n - 1] = 0;
        return shifted;
    }

